import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Shared world and settlements","description":"","frontmatter":{"pageId":"players/world","contentRevision":1},"headers":[],"relativePath":"en/players/world.md","filePath":"en/players/world.md"}'),n={name:"en/players/world.md"};function s(i,e,o,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="shared-world-and-settlements" tabindex="-1">Shared world and settlements <a class="header-anchor" href="#shared-world-and-settlements" aria-label="Permalink to &quot;Shared world and settlements&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>All players use the server planet. Choose an unoccupied tile when creating a colony. Foreign settlements show their owner, presence, last-seen time, colony age and wealth band where available.</p><p>Caravans and transport pods offer actions at another settlement: transfer, raid, visit or live, depending on mode, host availability and server policy. Read the action label before confirming: a visit and a real raid are not interchangeable.</p><p>The guild overlay is optional and does not replace normal map markers.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The default is one settlement per player. An offline marker does not mean the map keeps simulating. Peaceful mode disables some actions.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./visits">Visits and shops</a></li><li><a href="./raids-incidents">Raids and paid incidents</a></li><li><a href="./guild-influence">Guild influence</a></li></ul>',10)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
